CREATE POLICY "Admins upload journal media" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'journal-media' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins update journal media" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'journal-media' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins delete journal media" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'journal-media' AND public.has_role(auth.uid(), 'admin'));